# COMMAND ----------

CATALOG, SCHEMA = "workspace", "approval_copilot"
SCHEMA_TAGS = {'domain': 'payments', 'data_origin': 'synthetic'}
TABLE_TAGS = {'bronze_orchestrator': {'layer': 'bronze'},
 'bronze_acquirer_a': {'layer': 'bronze'},
 'bronze_acquirer_b': {'layer': 'bronze'},
 'bronze_acquirer_c': {'layer': 'bronze'},
 'ref_merchants': {'layer': 'reference'},
 'ref_issuers': {'layer': 'reference'},
 'ref_acquirers': {'layer': 'reference'},
 'ref_routing_rules': {'layer': 'reference'},
 'ref_decline_code_map': {'layer': 'reference'},
 'ref_change_log': {'layer': 'reference'},
 'ref_fx_rates': {'layer': 'reference'},
 'ref_country_tz': {'layer': 'reference'},
 'silver_payment_intents': {'layer': 'silver'},
 'silver_auth_attempts': {'layer': 'silver'},
 'silver_dq_quarantine': {'layer': 'silver'},
 'silver_payments': {'layer': 'silver'},
 'gold_approval_daily': {'layer': 'gold'},
 'gold_approval_hourly': {'layer': 'gold'},
 'gold_decline_reasons_daily': {'layer': 'gold'},
 'gold_cascade_daily': {'layer': 'gold'},
 'gold_issuer_daily': {'layer': 'gold'},
 'gold_funnel_daily': {'layer': 'gold'},
 'gold_anomalies_daily': {'layer': 'gold'},
 'gold_cascade_alerts_daily': {'layer': 'gold'},
 'gold_change_log': {'layer': 'gold'},
 'gold_change_guardrail': {'layer': 'gold'},
 'gold_dq_summary': {'layer': 'gold'},
 'gold_volume_alerts_daily': {'layer': 'gold'}}
COLUMN_TAGS = {('bronze_orchestrator', 'card_bin'): {'pci': 'truncated_pan'},
 ('bronze_orchestrator', 'card_last4'): {'pci': 'truncated_pan'},
 ('silver_payment_intents', 'card_bin'): {'pci': 'truncated_pan'},
 ('silver_payment_intents', 'card_last4'): {'pci': 'truncated_pan', 'column_mask': 'mask_card_last4'}}

# COMMAND ----------

def tags_sql(tags):
    return ", ".join(f"'{k}' = '{v}'" for k, v in tags.items())


def object_kind(full_name):
    rows = spark.sql(f"DESCRIBE TABLE EXTENDED {full_name}").collect()  # noqa: F821
    kind = {r[0].strip(): (r[1] or '').strip() for r in rows if r[0]}.get('Type', '').upper()
    if 'MATERIALIZED' in kind:
        return 'MATERIALIZED VIEW'
    return 'STREAMING TABLE' if 'STREAMING' in kind else 'TABLE'


failed = []
spark.sql(f"ALTER SCHEMA {CATALOG}.{SCHEMA} SET TAGS ({tags_sql(SCHEMA_TAGS)})")  # noqa: F821
for table, tags in TABLE_TAGS.items():
    full = f"{CATALOG}.{SCHEMA}.{table}"
    try:
        spark.sql(f"ALTER {object_kind(full)} {full} SET TAGS ({tags_sql(tags)})")  # noqa: F821
    except Exception as e:
        failed.append((table, str(e).strip().splitlines()[0]))
for (table, column), tags in COLUMN_TAGS.items():
    full = f"{CATALOG}.{SCHEMA}.{table}"
    try:
        spark.sql(f"ALTER {object_kind(full)} {full} ALTER COLUMN {column} SET TAGS ({tags_sql(tags)})")  # noqa: F821
    except Exception as e:
        failed.append((f"{table}.{column}", str(e).strip().splitlines()[0]))
print(f"tags set on {len(TABLE_TAGS) - len([f for f in failed if '.' not in f[0]])} tables")

# COMMAND ----------

# The mask: outside payments_support, every value reads ****.
for table in ['silver_payment_intents']:
    row = spark.sql("SELECT is_account_group_member('payments_support') AS member, "  # noqa: F821
                    "count_if(card_last4 <> '****') AS visible, count(*) AS total "
                    f"FROM workspace.approval_copilot.{table}").first()
    print(f"{table}: payments_support member: {row.member}; visible last-four values: {row.visible:,} of {row.total:,}")
    if not row.member and row.visible:
        failed.append((f"{table}.card_last4", "mask is not hiding the last four digits"))

# COMMAND ----------

# Table lineage recorded by Unity Catalog (system tables, when the workspace exposes them).
try:
    lineage = spark.sql(  # noqa: F821
        f"""SELECT DISTINCT source_table_name AS source, target_table_name AS target
        FROM system.access.table_lineage
        WHERE target_table_catalog = '{CATALOG}' AND target_table_schema = '{SCHEMA}'
          AND source_table_schema = '{SCHEMA}'
        ORDER BY target, source""").collect()
    print(f"{len(lineage)} lineage edges recorded")
    for r in lineage:
        print(f"  {r.source} -> {r.target}")
except Exception as e:
    print("Lineage system table not available here:", str(e).strip().splitlines()[0])

# COMMAND ----------

if failed:
    for f in failed:
        print("failed:", f)
    raise RuntimeError(f"{len(failed)} governance steps failed")
